void mapcryptunderground_01_function(struct ScreenAttr *screenAttribute, struct CharacterCollection *characterCollection, 
	struct MapInfo *mapInfo, struct ControlTypePool* controlPool, struct CharacterActionCollection *charActionCollection, 
	struct Track *track) {
	BoundingBox attackinstructions_area = {19, 266, 56, 357, 0, 255};
	CharacterAttr *character;
	BoundingBox charBB;
	int i, count;
	for (i = 0; i < characterCollection->currentSize; i++) {
		character = characterCollection->characters[i];
		if (character->type == ALISA) {
			break;
		}
	}
	
	if (character->type != ALISA) {
		return;
	}
	
	character->getBounds(character, &count, &charBB);
	
	if (isOverlap(&charBB, &attackinstructions_area)) {
		mprinter_printf("You can do 3 consecutive\nattacks. The last is slow\nbut more powerful\nthan the first 2 combined");
	}
}

